"""Direct observed RO body comparison; separate inferred own weapon/FX layers."""
import base64,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];OUT=ROOT/'research/sprite-animation/ro-attack-paintover-v22'
def url(p):return 'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode()
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 data=json.loads((OUT/'evidence/attempt3-registration-and-grip.json').read_text());cap=json.loads((OUT/'source/body-only/capture.json').read_text());fxroot=ROOT/'research/sprite-animation/motion-reference-v6/ro/attack-SE';fxcap=json.loads((fxroot/'capture.json').read_text());data['mapping']=[0,1,2,2,3,4,5,5,5]
 for f in data['frames']:assert sha(ROOT/f['path'])==f['sha256'];f['art']=url(ROOT/f['path']);f['RO']=url(OUT/'source/body-only'/cap['frames'][f['index']]['file']);f['ROFX']=url(fxroot/fxcap['frames'][f['index']]['file'])
 weapon=OUT/'raw/original-sword.png';data['weapon']={'url':url(weapon),'sha256':sha(weapon),'size':[887,1774],'grip_pixel':[443,1458],'point_pixel':[443,80],'runtime_scale':.115,'scope':'Own original generated prop. Observed palm socket; orientation and polar trail are authored approximations, not recovered RO weapon bones.'}
 html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RO attack direct paintover v22</title><style>body{font:15px system-ui;background:#181b20;color:#e9edf3;padding:20px;max-width:1400px;margin:auto}h1{font-size:23px}nav{display:flex;gap:10px;flex-wrap:wrap;align-items:center}button,input{font:inherit}button{background:#303844;color:white;border:1px solid #69778a;border-radius:5px;padding:8px}#panels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:18px}canvas{width:100%;height:auto;background:#272727}small{display:block;color:#bec7d4}#strip{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:4px;margin:18px 0}#phase{width:min(350px,70vw)}#status{min-height:45px}@media(max-width:700px){body{padding:12px}#panels{grid-template-columns:repeat(2,minmax(0,1fr))}#strip{grid-template-columns:repeat(3,minmax(0,1fr))}}</style><h1>วาดทับท่าโจมตี RO · v22</h1><p>9 ช่วงเวลา ×100ms / 6 โพสลำตัว · เก็บโพสค้างซ้ำตามภาพต้นแบบ</p><nav><button id="play">Play once</button><button id="reset">Restart</button><button id="prev">◀</button><button id="next">▶</button><label><input id="weapon" type="checkbox" checked>Own sword</label><label><input id="fx" type="checkbox" checked>Trail</label><label><input id="guides" type="checkbox">Observed points</label></nav><p><input id="phase" type="range" min="0" max="8" value="0"> <span id="clock"></span></p><p id="status"></p><div id="panels"><div><small>RO body pixels · fixed4× camera view</small><canvas id="ref" width="512" height="512"></canvas></div><div><small>Our direct body paintover · FX off</small><canvas id="body" width="512" height="512"></canvas></div><div><small>Our body + separate sword/trail</small><canvas id="main" width="512" height="512"></canvas></div><div><small>Captured RO weapon/FX · full capture view</small><canvas id="reffx" width="512" height="512"></canvas></div></div><div id="strip"></div><small>RO pixels/order/900ms container timing are observational authority. Community renderer timing is not original-client timing. Own weapon orientation, hidden joints, physical contacts and finger wrapping remain unverified; this is a review draft, not complete painted replacement parts.</small><script>const DATA=__DATA__;const $=id=>document.getElementById(id);const images=new Map();const state={time:0,playing:false,cancelled:false};
const key=t=>Math.min(8,Math.floor(Math.max(0,t)/100));const angle=i=>i<5?-150:i===5?40:45;
function span(i){const g=DATA.frames[i].right_grip_visible_palm_xy,deg=angle(i)*Math.PI/180,len=(DATA.weapon.grip_pixel[1]-DATA.weapon.point_pixel[1])*DATA.weapon.runtime_scale;return {base:g,tip:[g[0]+Math.cos(deg)*len,g[1]+Math.sin(deg)*len]}}
function fxGeometry(t,cancelled=false){const i=key(t),active=!cancelled&&t>=500&&t<880;if(!active)return {active:false,outer:[],inner:[],endpoint_error_px:null};const current=span(i),previous=span(4),out=[],inside=[];const da=(angle(i)-angle(4)+360)%360;const shrink=Math.min(1,(880-t)/180),from=1-shrink;for(let j=0;j<=20;j++){const u=from+(1-from)*j/20,base=previous.base.map((x,k)=>x+(current.base[k]-x)*u),a=(angle(4)+da*u)*Math.PI/180,r=(DATA.weapon.grip_pixel[1]-DATA.weapon.point_pixel[1])*DATA.weapon.runtime_scale;out.push([base[0]+Math.cos(a)*r,base[1]+Math.sin(a)*r]);inside.push([base[0]+Math.cos(a)*r*.66,base[1]+Math.sin(a)*r*.66])}const p=out.at(-1);return {active:true,outer:out,inner:inside,winding:'clockwise_overhead',sweep_degrees:da,alpha:.70*Math.min(1,(880-t)/120),endpoint_error_px:Math.hypot(p[0]-current.tip[0],p[1]-current.tip[1])}}
function drawFX(ctx,t,cancelled=false){const g=fxGeometry(t,cancelled);if(!g.active)return g;ctx.save();ctx.globalAlpha=g.alpha;ctx.beginPath();g.outer.forEach((p,j)=>j?ctx.lineTo(...p):ctx.moveTo(...p));[...g.inner].reverse().forEach(p=>ctx.lineTo(...p));ctx.closePath();const grad=ctx.createLinearGradient(...g.outer[0],...g.outer.at(-1));grad.addColorStop(0,'rgba(255,218,137,0)');grad.addColorStop(.65,'rgba(255,246,220,.65)');grad.addColorStop(1,'#fffdf3');ctx.fillStyle=grad;ctx.fill();ctx.beginPath();g.outer.forEach((p,j)=>j?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#fff7d9';ctx.lineWidth=2;ctx.stroke();ctx.restore();return g}
function drawWeapon(ctx,i){const p=DATA.frames[i].right_grip_visible_palm_xy;ctx.save();ctx.translate(...p);ctx.rotate((angle(i)+90)*Math.PI/180);ctx.scale(DATA.weapon.runtime_scale,DATA.weapon.runtime_scale);ctx.drawImage(images.get(DATA.weapon.url),-DATA.weapon.grip_pixel[0],-DATA.weapon.grip_pixel[1]);ctx.restore()}
function paint(c,im){const ctx=c.getContext('2d');ctx.clearRect(0,0,512,512);ctx.drawImage(im,0,0)}
function render(t=state.time){state.time=t;const i=key(t),f=DATA.frames[i];$('phase').value=i;$('clock').textContent=`${Math.round(t)}ms · exposure${i+1}/9 · body key${DATA.mapping[i]+1}/6`;
let ctx=$('ref').getContext('2d');ctx.clearRect(0,0,512,512);ctx.imageSmoothingEnabled=false;ctx.drawImage(images.get(f.RO),126,50,260,380);paint($('body'),images.get(f.art));ctx=$('main').getContext('2d');ctx.clearRect(0,0,512,512);ctx.drawImage(images.get(f.art),0,0);if($('weapon').checked)drawWeapon(ctx,i);const geom=drawFX(ctx,t,state.cancelled||!$('fx').checked);if($('weapon').checked){ctx.save();ctx.beginPath();ctx.ellipse(...f.right_grip_visible_palm_xy,17,15,0,0,Math.PI*2);ctx.clip();ctx.drawImage(images.get(f.art),0,0);ctx.restore()}ctx=$('reffx').getContext('2d');ctx.clearRect(0,0,512,512);ctx.imageSmoothingEnabled=false;ctx.drawImage(images.get(f.ROFX),64,32,384.8,447.7);
if($('guides').checked){for(const id of ['body','main']){const c=$(id).getContext('2d'),p=f.right_grip_visible_palm_xy;c.strokeStyle='#00dcff';c.beginPath();c.arc(...p,5,0,Math.PI*2);c.stroke()}const r=DATA.keys[DATA.mapping[i]];for(const [p,col]of[[r.calibration_surface_xy,'#2895ff'],[r.held_out_other_boot_xy,'#ff981d']]){const c=$('body').getContext('2d');c.fillStyle=col;c.beginPath();c.arc(...p,3,0,Math.PI*2);c.fill()}}
$('status').textContent=`Captured pose order / exact reused body holds · ${i===2||i===3?'exposures3–4 share ONE body image':i>=6?'exposures7–9 share ONE body image':''} · independent other-boot surface deltas retained for review; no anatomy PASS.`;
for(let j=0;j<9;j++){const c=$('strip').children[j].querySelector('canvas');paint(c,images.get(DATA.frames[j].art));c.style.outline=j===i?'2px solid #d7b671':'none'}$('play').textContent=state.playing?'Pause':'Play once';return {key:i,body_key:DATA.mapping[i],fx_active:geom.active,trail_endpoint_error_px:geom.endpoint_error_px,grip:f.right_grip_visible_palm_xy}}
function setTime(t){state.playing=false;state.cancelled=false;return render(t)};$('phase').oninput=()=>setTime(Number($('phase').value)*100);$('reset').onclick=()=>setTime(0);$('prev').onclick=()=>setTime(Math.max(0,key(state.time)-1)*100);$('next').onclick=()=>setTime(Math.min(8,key(state.time)+1)*100);$('play').onclick=()=>{if(state.time>=900)state.time=0;state.playing=!state.playing;render()};for(const id of['weapon','fx','guides'])$(id).onchange=()=>render();let last=performance.now();function tick(now){if(state.playing){state.time+=now-last;if(state.time>=900){state.time=900;state.playing=false}render()}last=now;requestAnimationFrame(tick)}
async function init(){for(const f of DATA.frames)for(const src of[f.art,f.RO,f.ROFX])if(!images.has(src)){const im=new Image();im.src=src;await im.decode();images.set(src,im)}const sword=new Image();sword.src=DATA.weapon.url;await sword.decode();images.set(DATA.weapon.url,sword);for(let i=0;i<9;i++){const c=document.createElement('div');c.innerHTML=`<small>${i+1} / body${DATA.mapping[i]+1}</small><canvas width="512"height="512"></canvas>`;$('strip').append(c)}render();window.ROQA={DATA,state,key,setTime,render,cancel(){state.cancelled=true;render()},fxGeometry,span,drawFX(t,c){const ctx=c.getContext('2d');ctx.clearRect(0,0,512,512);return drawFX(ctx,t)}};requestAnimationFrame(tick)}init();</script></html>'''
 (OUT/'review.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))));print('RO_REVIEW_READY',len((OUT/'review.html').read_bytes()))
if __name__=='__main__':main()
